from click.testing import CliRunner
import click
import pytest

class Foo:
    pass

class Bar:
    pass

@click.command()
@click.option("--foo", "ty", flag_value=Foo, type=click.UNPROCESSED, default=True)
@click.option("--bar", "ty", flag_value=Bar, type=click.UNPROCESSED)
def main(ty):
    click.echo(f"Value: {ty}")
    # In the reported issue, ty becomes an instance of Foo.
    # We want it to be the class Foo itself.
    if isinstance(ty, Foo):
        raise ValueError("Foo was instantiated!")

def test_flag_value_not_instantiated():
    runner = CliRunner()
    result = runner.invoke(main, [])
    assert result.exit_code == 0
    # The output should show the class, not an object.
    # The user says "this prints <__main__.Foo object at 0x10bed92b0>"
    assert "Foo object" not in result.output
    # It should look like the class: "<class '__main__.Foo'>"
    assert "<class" in result.output

import click
import pytest
from click.testing import CliRunner

# Create a custom class that behaves like semver.Version
class BadlyBehavingDefault:
    def __init__(self, value):
        self.value = value

    def __eq__(self, other):
        if other == "":
            raise ValueError("cannot compare with empty string")
        return self.value == other

    def __str__(self):
        return self.value

def test_custom_default_help():
    @click.command()
    @click.option(
        "--my-opt",
        default=BadlyBehavingDefault("1.0.0"),
        show_default=True,
    )
    def cli(my_opt):
        pass

    runner = CliRunner()
    result = runner.invoke(cli, ["--help"])
    assert result.exit_code == 0
    assert "1.0.0" in result.output
